parameters.jsCode:
const inspection = $input.first().json;

const config = $('Set Expected Version').first().json;

const expectedVersion = Number(config.expected_version);

const tableExists =
  inspection.migration_table_exists === true;

const shapeValid =
  inspection.migration_table_shape_valid === true;

const migrationRows =
  Number(inspection.migration_rows ?? 0);

const currentVersion =
  inspection.current_version !== null &&
  inspection.current_version !== undefined
    ? Number(inspection.current_version)
    : null;

let schemaState;
let reason;

// Banco novo
if (!tableExists) {

  schemaState = 'absent';
  reason = 'schema_migrations table does not exist';

}

// Existe algo chamado schema_migrations,
// mas não é a estrutura que esperamos
else if (!shapeValid) {

  schemaState = 'unsupported';
  reason = 'schema_migrations exists but has an unsupported structure';

}

// Tabela existe porém vazia.
// Não considero isso "banco novo" porque pode ser bootstrap incompleto.
else if (migrationRows === 0 || currentVersion === null) {

  schemaState = 'unsupported';
  reason = 'schema_migrations exists but contains no migration records';

}

// Exatamente a versão suportada
else if (currentVersion === expectedVersion) {

  schemaState = 'current';
  reason = `schema version ${currentVersion} matches expected version ${expectedVersion}`;

}

// Banco mais antigo
else if (currentVersion < expectedVersion) {

  schemaState = 'drift';
  reason = `schema version ${currentVersion} is behind expected version ${expectedVersion}`;

}

// Banco mais novo que o workflow
else {

  schemaState = 'unsupported';
  reason = `schema version ${currentVersion} is newer than supported version ${expectedVersion}`;

}

return [
  {
    json: {
      ...inspection,

      expected_version: expectedVersion,

      schema_state: schemaState,

      reason
    }
  }
];

parameters.errorMessage:
={{
  'Schema drift detected. Expected version '
  + $json.expected_version
  + ', but database is at version '
  + $json.current_version
  + '. '
  + $json.reason
}}

